// The course registry and the rest of the vault's configuration, read from <vault>/_agent/uni-os.json.
// That file is generated by the Uni OS CLI (`python tools/uni_os.py render`) from _agent/uni-os.toml, so the
// cockpit never hard-codes a course, a colour, a calendar, a time zone or a schedule. Pure: no Obsidian imports.
//
// The registry is process-wide state: the plugin builds it once at load (and again when uni-os.json changes)
// and calls setRegistry(); the tests do the same with a fixture. Everything else reads registry().

import { escapeRe } from "./md";

export type Scheme = "none" | "threshold" | "points" | "best-n" | "custom";
export type FeedRole = "classes" | "study" | "personal";

export interface Assessment {
  name: string;
  /** sheet | quiz | oral | project | midterm | other */
  kind: string;
  /** bonus | grade | admission | none */
  countsFor: string;
  /** solo | hints-only | coach | full ("" = the course's level) */
  assistance: string;
  pointsMax: number | null;
  /** Dated sittings ("YYYY-MM-DD" or "YYYY-MM-DD HH:MM"), used to count how many are left. */
  dates: string[];
}

export interface BonusRule {
  scheme: Scheme;
  description: string;
  /** Free text from the config, shown next to every number. */
  rule: string;
  /** Size of the full bonus: grade units (0.25) or, with maxIsPercent, percent of the grade. */
  maxBonus: number;
  maxIsPercent: boolean;
  /** threshold: share of the total that gives the full bonus (0.8 = 80 %). */
  threshold: number;
  /** Total points if published (0 = unknown; the card's "~N pts" in bonus_target is then the estimate). */
  total: number;
  totalEstimated: boolean;
  /** threshold / best-n: below the mark you get a proportional share (false = all or nothing). */
  proportional: boolean;
  /** points: points that give the full bonus (0 = the total, i.e. linear with no slack). */
  fullAt: number;
  /** best-n: how many assessments must be passed. */
  required: number;
  /** Label of the points ("points", "quiz points", "oral points"). */
  unit: string;
  /** Names of the assessments whose dates count as "left" (empty = all that count for the bonus). */
  counts: string[];
}

export interface CourseInfo {
  id: string;
  name: string;
  short: string;
  folder: string;
  slug: string;
  /** Main colour (lectures). */
  colour: string;
  /** Lighter colour (exercise classes). */
  colourLight: string;
  aliases: string[];
  /** Compiled detection patterns: short name, full name, aliases (and an optional raw `detect` regex). */
  detect: RegExp[];
  /** The course card: <folder>/<slug>.md */
  card: string;
  errorLogs: Array<{ path: string; label: string }>;
  /** Folders whose newest notes are listed per course (study pages, quiz prep). */
  studyFolders: string[];
  assistance: string;
  assessments: Assessment[];
  bonus: BonusRule;
}

export interface Registry {
  /** Where it came from: the config path, or "built-in defaults". */
  source: string;
  loaded: boolean;
  /** Problems found while reading (shown as warnings in the cockpit). */
  problems: string[];
  student: { name: string; handle: string; language: string };
  university: { name: string; short: string; programme: string };
  term: { label: string; timezone: string; week0: string | null; lastLectureDay: string; examStart: string; examEnd: string };
  courses: CourseInfo[];
  schedule: { prepRuns: string[]; prepCheck: string; syncTimes: string[]; studyCutoff: string };
  calendars: Array<{ id: string; label: string; role: FeedRole }>;
  paths: { agentDir: string; inbox: string; status: string; weeks: string; prep: string; plans: string; snapshot: string; rules: string; prompt: string; overview: string };
  vocab: { done: string[]; pending: string[]; noBonus: string[]; softPrefixes: string[]; softMarkers: string[]; notReleased: string[] };
  headings: { due: string; results: string; notes: string; checkIn: string; next: string; exercises: string; selfRating: string; snapshot: string };
  notation: { lecture: RegExp; exercise: RegExp; optional: RegExp; deep: RegExp; focus: string; main: string };
  models: { fast: string; strong: string };
  replyRules: string[];
  /**
   * The enabled modules (modules.enabled), or null when the file doesn't list them (a hand-written or older
   * uni-os.json): then every optional part is shown. Sections that only make sense with an optional module (the
   * prep card needs daily-prep, the "applied at 13:15" texts need inbox-sync) check it with moduleEnabled().
   */
  modules: string[] | null;
  /** The raw [cockpit] table, for first-run plugin settings. */
  cockpit: Record<string, unknown>;
}

// ---------- small readers (the JSON comes from a TOML file a person edits: be forgiving) ----------

type Obj = Record<string, unknown>;
const obj = (v: unknown): Obj => (v && typeof v === "object" && !Array.isArray(v) ? (v as Obj) : {});
const str = (v: unknown, d = ""): string => (typeof v === "string" ? v : typeof v === "number" ? String(v) : d);
const numv = (v: unknown, d = 0): number => (typeof v === "number" && isFinite(v) ? v : typeof v === "string" && v.trim() !== "" && isFinite(+v) ? +v : d);
const bool = (v: unknown, d: boolean): boolean => (typeof v === "boolean" ? v : d);
const list = (v: unknown): string[] => (Array.isArray(v) ? v.map((x) => str(x)).filter(Boolean) : typeof v === "string" && v ? [v] : []);
const time = (v: unknown, d: string): string => {
  const s = str(v, d).trim();
  return /^\d{1,2}:\d{2}$/.test(s) ? s.padStart(5, "0") : d;
};
/** A date from TOML arrives as "YYYY-MM-DD" (or a full ISO string): keep the day. */
const day = (v: unknown): string => {
  const m = /^(\d{4}-\d{2}-\d{2})/.exec(str(v));
  return m ? m[1] : "";
};

export const DEFAULT_VOCAB: Registry["vocab"] = {
  done: ["✓", "done", "submitted", "closed", "handed in", "uploaded", "dropped", "skipped"],
  pending: ["not reported", "pending", "not recorded"],
  noBonus: ["none", "no", "feedback only"],
  softPrefixes: ["tutorial"],
  softMarkers: ["(tentative)"],
  notReleased: ["not released"],
};

export const DEFAULT_HEADINGS: Registry["headings"] = {
  due: "Due this week",
  results: "Results this week",
  notes: "Notes",
  checkIn: "End-of-week check-in",
  next: "Next 10 days",
  exercises: "Exercises",
  selfRating: "Self-rated",
  snapshot: "Snapshot:",
};

export const DEFAULT_NOTATION = {
  lecture: "^(?:V|L):",
  exercise: "^(?:U|Ü|E):",
  optional: "^\\(|^OP\\b",
  deep: "\\bdeep\\b",
  focus: "FOCUS:",
  main: "_",
};

export const DEFAULT_MODELS = { fast: "claude-haiku-5-5", strong: "claude-sonnet-5-5" };

const CAL_ROLE: Record<string, FeedRole> = { courses: "classes", study_blocks: "study", events: "personal", busy: "personal" };
const CAL_DEFAULT_LABEL: Record<string, string> = { courses: "Courses", study_blocks: "Study blocks", events: "Events", busy: "Busy" };

function systemTimeZone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    return "UTC";
  }
}

function validTimeZone(tz: string): boolean {
  try {
    new Intl.DateTimeFormat("en-GB", { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

/**
 * A regex from the config: "pattern" or "/pattern/flags". Falls back to `fallback` when the key is missing or the
 * pattern doesn't compile; an explicitly empty string switches the pattern off (it then never matches).
 */
function regex(v: unknown, fallback: string, flags = "", problems?: string[], key = ""): RegExp {
  const s = str(v, fallback);
  if (!s.trim()) return /(?!)/;
  const m = /^\/(.*)\/([a-z]*)$/.exec(s);
  try {
    return m ? new RegExp(m[1], m[2]) : new RegExp(s, flags);
  } catch {
    problems?.push(`${key} is not a valid regular expression; using the default.`);
    return new RegExp(fallback, flags);
  }
}

/** A title pattern that also accepts a literal prefix ("L:") at the start. */
function withPrefix(re: RegExp, prefix: string): RegExp {
  const p = prefix.trim();
  return p ? new RegExp(`(?:${re.source})|^${escapeRe(p)}`, re.flags) : re;
}

/**
 * One detection pattern per term. Short all-caps codes ("LA", "DM", "AD") match case-sensitively, so the word
 * "la" in a sentence doesn't count; everything else ignores case. A term only matches as a whole word, but the
 * block notation's "_" may follow it ("LA_ mock").
 */
export function termPattern(term: string): RegExp {
  const pre = /^[A-Za-z0-9]/.test(term) ? "(?<![A-Za-z0-9])" : "";
  const post = /[A-Za-z0-9]$/.test(term) ? "(?![A-Za-z0-9])" : "";
  const caseSensitive = term.length <= 5 && term === term.toUpperCase() && /[A-Z]/.test(term);
  return new RegExp(pre + escapeRe(term) + post, caseSensitive ? "" : "i");
}

/** Mixes a #rrggbb colour with white (amount 0..1; 0.4 = the 40 % tint the config schema uses for colour_light). */
export function lighten(hex: string, amount = 0.4): string {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim());
  if (!m) return hex;
  const h = m[1].length === 3 ? m[1].replace(/./g, "$&$&") : m[1];
  const c = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
  return "#" + c.map((v) => Math.round(v + (255 - v) * amount).toString(16).padStart(2, "0")).join("");
}

const FALLBACK_COLOURS = ["#1e66f5", "#40a02b", "#8839ef", "#d20f39", "#fe640b", "#179299", "#df8e1d", "#ea76cb"];

function readBonus(raw: unknown): BonusRule {
  const b = obj(raw);
  const schemes: Scheme[] = ["none", "threshold", "points", "best-n", "custom"];
  const scheme = (schemes as string[]).includes(str(b.scheme)) ? (str(b.scheme) as Scheme) : str(b.scheme) ? "custom" : "none";
  // max_bonus = 0.25 (grade units) or "10%" (percent of the grade); 0 or missing = not known (the config's default)
  const maxRaw = b.max_bonus;
  const maxIsPercent = typeof maxRaw === "string" && /%\s*$/.test(maxRaw);
  const maxBonus = maxIsPercent ? parseFloat(String(maxRaw)) || 0 : numv(maxRaw, 0);
  let threshold = numv(b.threshold, 0.8);
  if (threshold > 1) threshold = threshold / 100; // "80" means 80 %
  return {
    scheme,
    description: str(b.description),
    rule: str(b.rule),
    maxBonus,
    maxIsPercent,
    threshold: threshold > 0 ? threshold : 0.8,
    total: numv(b.total, 0),
    totalEstimated: bool(b.total_estimated, false),
    proportional: bool(b.proportional, true),
    fullAt: numv(b.full_at, 0),
    required: numv(b.required, 0),
    unit: str(b.unit, "points") || "points",
    counts: list(b.counts),
  };
}

function readCourse(raw: unknown, index: number, studyFolders: string[], problems: string[]): CourseInfo | null {
  const c = obj(raw);
  const id = str(c.id).trim();
  if (!id) {
    problems.push(`Course ${index + 1} in uni-os.json has no id; it is skipped.`);
    return null;
  }
  const short = str(c.short, id.toUpperCase());
  const name = str(c.name, short);
  const folder = str(c.folder, short).replace(/\/+$/, "");
  const slug = str(c.slug, id);
  const colour = str(c.colour) || str(c.color) || FALLBACK_COLOURS[index % FALLBACK_COLOURS.length];
  const colourLight = str(c.colour_light) || str(c.color_light) || lighten(colour);
  const aliases = list(c.aliases);
  const detect: RegExp[] = [];
  for (const term of [short, name, ...aliases]) if (term.trim()) detect.push(termPattern(term.trim()));
  if (str(c.detect).trim()) detect.push(regex(c.detect, "(?!)", "", problems, `courses.${id}.detect`));
  const streams = list(c.error_log_streams);
  const prefix = folder ? `${folder}/` : "";
  const errorLogs =
    streams.length > 1
      ? streams.map((s) => ({ path: `${prefix}${slug}-error-log-${s}.md`, label: `Error log: ${s}` }))
      : [{ path: `${prefix}${slug}-error-log.md`, label: "Error log" }];
  const assessments: Assessment[] = (Array.isArray(c.assessments) ? c.assessments : []).map((a) => {
    const x = obj(a);
    return {
      name: str(x.name, "assessment"),
      kind: str(x.kind, "other"),
      countsFor: str(x.counts_for, "bonus"),
      assistance: str(x.assistance),
      pointsMax: x.points_max === undefined ? null : numv(x.points_max, 0),
      dates: list(x.dates),
    };
  });
  return {
    id,
    name,
    short,
    folder,
    slug,
    colour,
    colourLight,
    aliases,
    detect,
    card: `${prefix}${slug}.md`,
    errorLogs,
    studyFolders: studyFolders.map((s) => `${prefix}${s.replace(/\/+$/, "")}/`),
    assistance: str(c.assistance, "hints-only"),
    assessments,
    bonus: readBonus(c.bonus),
  };
}

/** Builds the registry from the parsed uni-os.json (or null when there is none). Never throws. */
export function buildRegistry(json: unknown, source = "_agent/uni-os.json"): Registry {
  const problems: string[] = [];
  const root = obj(json);
  const loaded = json !== null && json !== undefined;
  if (!loaded) problems.push(`No ${source} found, so the cockpit knows no courses. Run \`python tools/uni_os.py render\` in the framework folder (it writes this file from uni-os.toml).`);

  const student = obj(root.student);
  const uni = obj(root.university);
  const term = obj(root.term);
  const paths = obj(root.paths);
  const schedule = obj(root.schedule);
  const calendar = obj(root.calendar);
  const cockpit = obj(root.cockpit);
  const agent = obj(root.agent);
  // `uni-os render` always writes the full list; an empty or missing one says nothing (the CLI then uses a preset).
  const enabled = list(obj(root.modules).enabled);

  let timezone = str(term.timezone) || systemTimeZone();
  if (!validTimeZone(timezone)) {
    problems.push(`term.timezone "${timezone}" is not a time zone this device knows; using ${systemTimeZone()}.`);
    timezone = systemTimeZone();
  }
  const week0 = day(term.week0_monday) || null;
  if (loaded && !week0) problems.push("term.week0_monday is missing, so week numbers can't be worked out (they show as week 0).");

  const studyFolders = list(cockpit.study_folders).length ? list(cockpit.study_folders) : ["notes", "quiz-prep"];
  const courses: CourseInfo[] = [];
  const seen = new Set<string>();
  (Array.isArray(root.courses) ? root.courses : []).forEach((raw, i) => {
    const c = readCourse(raw, i, studyFolders, problems);
    if (!c) return;
    if (seen.has(c.id)) {
      problems.push(`Course id "${c.id}" appears twice in uni-os.json; the second one is skipped.`);
      return;
    }
    seen.add(c.id);
    courses.push(c);
  });

  const agentDir = str(paths.agent_dir, "_agent").replace(/\/+$/, "") || "_agent";
  // An explicitly empty list switches a word class off; a missing key keeps the defaults.
  const pick = (tomlKey: string, d: string[]) => (Array.isArray(cockpit[tomlKey]) ? list(cockpit[tomlKey]) : d);
  const headingsRaw = obj(cockpit.headings);
  const h = (key: keyof Registry["headings"], tomlKey: string) => str(headingsRaw[tomlKey], DEFAULT_HEADINGS[key]) || DEFAULT_HEADINGS[key];

  const calendars: Registry["calendars"] = [];
  for (const id of Object.keys(CAL_ROLE)) {
    const label = str(calendar[id], CAL_DEFAULT_LABEL[id]);
    if (label) calendars.push({ id, label, role: CAL_ROLE[id] });
  }

  const dailyPrep = list(schedule.daily_prep).map((t) => time(t, "")).filter(Boolean);
  const sync = list(schedule.inbox_sync).map((t) => time(t, "")).filter(Boolean);

  return {
    source,
    loaded,
    problems,
    student: { name: str(student.name), handle: str(student.handle), language: str(student.language, "English") || "English" },
    university: { name: str(uni.name), short: str(uni.short), programme: str(uni.programme) },
    term: {
      label: str(term.label),
      timezone,
      week0,
      lastLectureDay: day(term.last_lecture_day),
      examStart: day(term.exam_session_start),
      examEnd: day(term.exam_session_end),
    },
    courses,
    schedule: {
      prepRuns: schedule.daily_prep === undefined ? ["17:30", "19:30"] : dailyPrep,
      prepCheck: schedule.prep_check === undefined ? "07:30" : time(schedule.prep_check, ""),
      syncTimes: schedule.inbox_sync === undefined ? ["07:15", "13:15", "18:15"] : sync,
      studyCutoff: schedule.study_cutoff === undefined ? "19:00" : time(schedule.study_cutoff, ""),
    },
    calendars,
    // An empty string means "the default" for every path (module.toml ships "" for the derived ones).
    paths: {
      agentDir,
      inbox: str(paths.inbox).replace(/\/+$/, "") || "inbox",
      status: str(cockpit.status_path).trim() || "progress/current-status.md",
      weeks: str(cockpit.weeks_folder).replace(/\/+$/, "") || "progress/weeks",
      prep: str(cockpit.prep_folder).replace(/\/+$/, "") || "semester/prep",
      plans: str(cockpit.plans_folder).replace(/\/+$/, "") || "semester/plans",
      snapshot: str(cockpit.snapshot_path).trim() || `${agentDir}/cockpit/calendar-snapshot.json`,
      rules: str(cockpit.rules_path).trim() || `${agentDir}/rules.md`,
      prompt: str(cockpit.prompt_note).trim() || `${agentDir}/cockpit/assistant-prompt.md`,
      overview: str(cockpit.overview_path).trim() || "courses-overview.md",
    },
    vocab: {
      done: pick("done_words", DEFAULT_VOCAB.done),
      pending: pick("pending_words", DEFAULT_VOCAB.pending),
      noBonus: pick("no_bonus_words", DEFAULT_VOCAB.noBonus),
      softPrefixes: pick("soft_prefixes", DEFAULT_VOCAB.softPrefixes),
      softMarkers: pick("soft_markers", DEFAULT_VOCAB.softMarkers),
      notReleased: pick("not_released_words", DEFAULT_VOCAB.notReleased),
    },
    headings: {
      due: h("due", "due"),
      results: h("results", "results"),
      notes: h("notes", "notes"),
      checkIn: h("checkIn", "check_in"),
      next: h("next", "next"),
      exercises: h("exercises", "exercises"),
      selfRating: h("selfRating", "self_rating"),
      snapshot: h("snapshot", "snapshot"),
    },
    notation: {
      // The planning module's title prefixes (calendar.lecture_prefix / exercise_prefix) always count too.
      lecture: withPrefix(regex(cockpit.lecture_pattern, DEFAULT_NOTATION.lecture, "", problems, "cockpit.lecture_pattern"), str(calendar.lecture_prefix)),
      exercise: withPrefix(regex(cockpit.exercise_pattern, DEFAULT_NOTATION.exercise, "", problems, "cockpit.exercise_pattern"), str(calendar.exercise_prefix)),
      optional: regex(cockpit.optional_pattern, DEFAULT_NOTATION.optional, "", problems, "cockpit.optional_pattern"),
      deep: regex(cockpit.deep_pattern, DEFAULT_NOTATION.deep, "i", problems, "cockpit.deep_pattern"),
      focus: str(cockpit.focus_marker, DEFAULT_NOTATION.focus) || DEFAULT_NOTATION.focus,
      main: str(cockpit.main_marker, DEFAULT_NOTATION.main) || DEFAULT_NOTATION.main,
    },
    models: { fast: str(cockpit.fast_model, DEFAULT_MODELS.fast) || DEFAULT_MODELS.fast, strong: str(cockpit.strong_model, DEFAULT_MODELS.strong) || DEFAULT_MODELS.strong },
    replyRules: list(agent.reply_rules),
    modules: enabled.length ? enabled : null,
    cockpit,
  };
}

let active: Registry = buildRegistry({}, "built-in defaults");

export function setRegistry(r: Registry): void {
  active = r;
}

export function registry(): Registry {
  return active;
}

/** Whether an optional module is enabled (modules.enabled); true when the config doesn't list the modules. */
export function moduleEnabled(id: string, reg: Registry = active): boolean {
  return !reg.modules || reg.modules.includes(id);
}

export function courses(): CourseInfo[] {
  return active.courses;
}

export function courseById(id: string | null | undefined): CourseInfo | null {
  return id ? active.courses.find((c) => c.id === id) ?? null : null;
}

/** Short name of a course id, or the id itself. */
export function shortOf(id: string | null | undefined): string {
  return courseById(id)?.short ?? id ?? "";
}

/** Which course a piece of text (block title, table row) is about: the one mentioned first. */
export function detectCourse(text: string): string | null {
  const t = text.replace(/\*\*/g, "");
  let best: { id: string; at: number; len: number } | null = null;
  for (const c of active.courses) {
    for (const re of c.detect) {
      const m = re.exec(t);
      if (m && (!best || m.index < best.at || (m.index === best.at && m[0].length > best.len))) best = { id: c.id, at: m.index, len: m[0].length };
    }
  }
  return best?.id ?? null;
}

/** The course a prep-note callout type names (`> [!algo]`): its id, slug or short name, any case. */
export function calloutCourse(type: string): string | null {
  const t = type.toLowerCase();
  return active.courses.find((c) => c.id.toLowerCase() === t || c.slug.toLowerCase() === t || c.short.toLowerCase() === t)?.id ?? null;
}

/** The role of a calendar (`cal` of an event): from the plugin's feed list, the registry, or the default names. */
export function calendarRole(cal: string, feeds: Array<{ id: string; role: FeedRole }> = []): FeedRole {
  const f = feeds.find((x) => x.id === cal) ?? active.calendars.find((x) => x.id === cal);
  if (f) return f.role;
  if (cal === "personal" || cal === "busy" || cal === "events") return "personal";
  if (cal === "courses" || cal === "classes") return "classes";
  return "study";
}

/** Course colours from the registry, with the plugin's per-course overrides on top. */
export function paletteOf(reg: Registry, overrides: Record<string, { main?: string; light?: string }> = {}): Record<string, { main: string; light: string }> {
  const out: Record<string, { main: string; light: string }> = {};
  for (const c of reg.courses) out[c.id] = { main: overrides[c.id]?.main || c.colour, light: overrides[c.id]?.light || c.colourLight };
  return out;
}

/** The person the notes are written about: name, else handle, else "the student". */
export function studentName(): string {
  return active.student.name || active.student.handle || "the student";
}

// ---------- vocabulary as regular expressions ----------

const word = (w: string) => escapeRe(w) + (/[A-Za-z0-9]$/.test(w) ? "\\b" : "");
let vocabCache: { reg: Registry; re: VocabRe } | null = null;

export interface VocabRe {
  /** Done only when the cell opens with it: "x done 2/2; y open" is still open. A score "3 / 4" counts too. */
  doneStart: RegExp;
  pending: RegExp;
  noBonus: RegExp;
  soft: RegExp;
  notReleased: RegExp;
}

export function vocab(): VocabRe {
  if (vocabCache?.reg === active) return vocabCache.re;
  const v = active.vocab;
  const alt = (xs: string[]) => (xs.length ? xs.map(word).join("|") : "(?!)");
  const softParts = [...v.softPrefixes.map((w) => "^" + word(w)), ...v.softMarkers.map(escapeRe)];
  const re: VocabRe = {
    doneStart: new RegExp(`^(?:${v.done.length ? v.done.map(word).join("|") + "|" : ""}\\d+(?:\\.\\d+)?\\s*\\/\\s*\\d+)`, "i"),
    pending: new RegExp(v.pending.length ? v.pending.map(escapeRe).join("|") : "(?!)", "i"),
    noBonus: new RegExp(`^(?:$|${alt(v.noBonus)})`, "i"),
    soft: new RegExp(softParts.length ? softParts.join("|") : "(?!)", "i"),
    notReleased: new RegExp(v.notReleased.length ? v.notReleased.map(escapeRe).join("|") : "(?!)", "i"),
  };
  vocabCache = { reg: active, re };
  return re;
}
